/**
 * Session insights dialog (⋯ → Session insights): an AI-generated summary of
 * the chat — outcome, what changed, risks & follow-ups — generated by the
 * chat's own agent via a marker run (```session-insights fence contract in
 * src/shared/session-insights.ts) and saved on the chat row, plus all-time
 * token-usage totals for the chat. Regenerate replaces the saved summary.
 */
import React, { useEffect, useRef, useState } from 'react'
import { NotebookText, RefreshCw } from 'lucide-react'
import { trpc } from '../../lib/trpc'
import { Dialog, DialogContent, DialogTitle } from '../../components/ui/dialog'
import { Button } from '../../components/ui/button'
import { Tip } from '../../components/ui/tooltip'
import { Markdown } from './Markdown'
import { timeAgo } from '../../lib/utils'
import { useAgentStream } from './use-agent-stream'
import {
  INSIGHTS_MARKER,
  buildInsightsPrompt,
  findCompletedInsights
} from '../../../../shared/session-insights'

export function InsightsDialog({
  chatId,
  subchatId,
  open,
  onOpenChange
}: {
  chatId: string
  /** Subchat whose agent generates the summary (the active conversation tab). */
  subchatId: string
  open: boolean
  onOpenChange: (open: boolean) => void
}): React.JSX.Element {
  const utils = trpc.useUtils()
  const saved = trpc.chats.getInsights.useQuery({ chatId }, { enabled: open })
  const usage = trpc.analytics.usageForChat.useQuery({ chatId }, { enabled: open })
  const setInsights = trpc.chats.setInsights.useMutation({
    onSuccess: () => utils.chats.getInsights.invalidate({ chatId })
  })
  const send = trpc.agent.send.useMutation()

  // Generation follows the shipped PR-draft pattern: send the prompt as a
  // marker run, watch the transcript while the dialog is open, and save the
  // parsed fence once the run goes idle.
  const [generating, setGenerating] = useState(false)
  const [genError, setGenError] = useState<string | null>(null)
  /** Marker id of a run already completed at click time — ignored as stale. */
  const baseline = useRef<string | null>(null)
  const stream = useAgentStream(open ? subchatId : null)

  useEffect(() => {
    // Closing the dialog abandons completion tracking (the run itself keeps
    // going in the chat); reopening starts clean.
    setGenerating(false)
    setGenError(null)
  }, [open, subchatId])

  const startGenerate = (): void => {
    baseline.current = findCompletedInsights(stream.messages)?.markerId ?? null
    setGenError(null)
    setGenerating(true)
    send.mutate(
      {
        subchatId,
        content: buildInsightsPrompt(),
        displayText: INSIGHTS_MARKER,
        displayKind: 'marker'
      },
      { onError: () => setGenerating(false) }
    )
  }
  const { mutate: saveInsights } = setInsights
  useEffect(() => {
    if (!generating || stream.running) return
    const done = findCompletedInsights(stream.messages)
    if (!done || done.markerId === baseline.current) return
    setGenerating(false)
    if (done.insights) {
      saveInsights({ chatId, insights: done.insights })
    } else {
      setGenError(
        'The agent finished without a usable session-insights block — try generating again.'
      )
    }
  }, [generating, stream.running, stream.messages, chatId, saveInsights])

  const busy = generating || stream.running
  const generateTip = busy
    ? 'A run is in progress — insights can be generated once the agent is idle'
    : saved.data?.insights
      ? 'Ask the agent to summarize the session again, replacing the saved insights'
      : 'Ask the agent to summarize this session — outcome, what changed, risks & follow-ups'

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl">
        <DialogTitle className="flex items-center gap-1.5">
          <NotebookText size={14} />
          Session insights
        </DialogTitle>
        <div className="flex items-center justify-between gap-2">
          <div className="text-[11px] text-muted-foreground">
            An AI summary of this chat, written by its agent from the conversation itself.
          </div>
          <Tip content={generateTip}>
            <span className="inline-flex shrink-0">
              <Button size="sm" variant="outline" disabled={busy} onClick={startGenerate}>
                <RefreshCw size={12} className={generating ? 'animate-spin' : ''} />
                {generating ? 'Generating…' : saved.data?.insights ? 'Regenerate' : 'Generate'}
              </Button>
            </span>
          </Tip>
        </div>
        {genError && <div className="text-[11px] text-destructive selectable">{genError}</div>}
        {send.error && (
          <div className="text-[11px] text-destructive selectable">{send.error.message}</div>
        )}
        <div className="max-h-[22rem] min-h-[8rem] overflow-y-auto rounded border border-border p-3">
          {saved.data?.insights ? (
            <Markdown text={saved.data.insights} />
          ) : (
            <div className="text-[11px] text-muted-foreground">
              {generating
                ? 'The agent is summarizing the session…'
                : 'No insights yet — Generate asks this chat\u2019s agent to summarize the session (outcome, what changed, risks & follow-ups).'}
            </div>
          )}
        </div>
        <div className="flex items-center justify-between text-[10px] text-muted-foreground">
          <span>
            {usage.data
              ? `Token usage: ${usage.data.totalTokens.toLocaleString()} total (${usage.data.inputTokens.toLocaleString()} in / ${usage.data.outputTokens.toLocaleString()} out) across ${usage.data.messages.toLocaleString()} messages`
              : 'Token usage: …'}
          </span>
          {saved.data?.insightsGeneratedAt && (
            <span>Generated {timeAgo(saved.data.insightsGeneratedAt)}</span>
          )}
        </div>
      </DialogContent>
    </Dialog>
  )
}
